"use strict";
const assert=require("node:assert/strict");
const crypto=require("node:crypto");
const {canonical,digest,verify}=require("../../security/local/security126-signed-snapshot.cjs");
const {TRUST}=require("../../security/local/security125-timestamp-provenance.cjs");
const {privateKey,publicKey}=crypto.generateKeyPairSync("ed25519");
const other=crypto.generateKeyPairSync("ed25519");
const publicKeys={test_key:publicKey.export({type:"spki",format:"pem"})};
const now=Date.parse("2026-11-17T10:00:00Z");
const metadata=[{game_id:2026020335,game_date:"2026-11-17",away_team:"EDM",home_team:"FLA",status:"pending"}];
const predictions=[{game_id:2026020335,core42_away:2,core42_home:3,core43_away:2.5,core43_home:3.5,core43_preview_away:2.6,core43_preview_home:3.4,away_gsax_per100:null,home_gsax_per100:1.2}];
const snapshot={metadata,predictions,metadataAsOf:"2026-11-17T09:59:00Z",predictionsAsOf:"2026-11-17T09:59:00Z"};
const evidence={algorithm:"Ed25519",key_id:"test_key",signature:crypto.sign(null,canonical(snapshot),privateKey).toString("base64")};
const args={snapshot,evidence,publicKeys,now};
assert.equal(verify(args).trust,TRUST.VERIFIED);
assert.equal(verify(args).rows.length,1);
assert.equal(verify(args).digest,digest(snapshot));
function denied(changes){const result=verify({...args,...changes});assert.equal(result.trust,TRUST.UNVERIFIED);assert.deepEqual(result.rows,[]);assert.equal(result.digest,null);}
denied({evidence:undefined});
denied({evidence:{...evidence,key_id:"unknown"}});
denied({evidence:{...evidence,signature:"a".repeat(88)}});
denied({publicKeys:{test_key:other.publicKey.export({type:"spki",format:"pem"})}});
denied({snapshot:{...snapshot,predictions:[{...predictions[0],core43_home:8}]}});
denied({snapshot:{...snapshot,metadata:[{...metadata[0],status:"final"}]}});
denied({snapshot:{...snapshot,metadataAsOf:"2026-11-17T09:58:00Z"}});
denied({snapshot:{...snapshot,predictions:[]}});
denied({now:now+3600000});
denied({now:now-3600000});
denied({snapshot:{...snapshot,metadata:[...metadata,...metadata]}});
assert.equal(digest({...snapshot,metadata:[{...metadata[0],private_token:"ignored"}]}),digest(snapshot));
console.log("SECURITY-126 synthetic Ed25519 integrity, tampering and freshness checks passed");
